const listRecoverablePositionCashOutBatchKeys = `-- name: ListRecoverablePositionCashOutBatchKeys :many
SELECT id
FROM worm_position_cash_out_batches
WHERE (
    (
      state IN ('BUILDING', 'QUEUED', 'RUNNING', 'PAUSE_REQUESTED')
      AND (next_poll_at IS NULL OR next_poll_at <= $1::timestamptz)
    )
    OR (
      state = 'TERMINATE_REQUESTED'
      AND (
        (next_poll_at IS NOT NULL AND next_poll_at <= $1::timestamptz)
        OR check_requested_at IS NOT NULL
      )
    )
    OR (
      state = 'RECONCILIATION_REQUIRED'
      AND check_requested_at IS NOT NULL
    )
    OR (
      state = 'PAUSED'
      AND check_requested_at IS NOT NULL
    )
  )
  AND (claim_id IS NULL OR claim_expires_at <= $1::timestamptz)
ORDER BY COALESCE(next_poll_at, updated_at), created_at, id
LIMIT $2::integer
`

